-- Yu'lon: WoW Forever Unbound's Mentor. Generated by `python -m yulon.forever_unbound_sql`
-- from yulon/forever_unbound_catalog.py; do not edit by hand.
--
-- The Mentor teaches a character spells of other classes, to every class with mana, for the price
-- the spell's own class trainers charge. Its script (npc_yulon_mentor, in Yu'lon's server image)
-- takes the option's BoxMoney, then teaches the option's SpellID. Only Yu'lon's reserved ids are
-- touched (3100001-3100020 and 3100100-3100399), deleted first, so the file can be applied again;
-- that also removes phase 1's server-side teach spells and SmartAI rows.
--
-- The multi-class design is Wrath Unbound's (DaddyCool, Dad's MMO Lab). ForeverCore is advocaite's
-- Forever core on TrinityCore, with Karrz's PlayerbotV2 bots.

DELETE FROM `creature` WHERE `guid` BETWEEN 3100001 AND 3100006;
DELETE FROM `creature_template` WHERE `entry` = 3100001;
DELETE FROM `creature_template_model` WHERE `CreatureID` = 3100001;
DELETE FROM `creature_template_difficulty` WHERE `Entry` = 3100001;
DELETE FROM `creature_template_gossip` WHERE `CreatureID` = 3100001;
DELETE FROM `gossip_menu` WHERE `MenuID` BETWEEN 3100001 AND 3100020;
DELETE FROM `gossip_menu_option` WHERE `MenuID` BETWEEN 3100001 AND 3100020;
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 15 AND `SourceGroup` BETWEEN 3100001 AND 3100020;
DELETE FROM `smart_scripts` WHERE `entryorguid` = 3100001 AND `source_type` = 0;
DELETE FROM `serverside_spell` WHERE `Id` BETWEEN 3100100 AND 3100399;
DELETE FROM `serverside_spell_effect` WHERE `SpellID` BETWEEN 3100100 AND 3100399;

